<?php
$u=$workspaceUser??auth();$uid=(int)$u['id'];$admin=has($u,['admin']);$super=has($u,['supervisor']);$finance=has($u,['finance']);$agent=has($u,['agent']);$field=has($u,['field_agent']);$provider=has($u,['provider']);$staff=$admin||$super;
$scope=$staff?'1=1':($agent?'EXISTS(SELECT 1 FROM appointments ax WHERE ax.property_id=t.property_id AND ax.assigned_to='.$uid.')':'(t.head_tenant_id='.$uid.' OR p.owner_id='.$uid.' OR EXISTS(SELECT 1 FROM tenancy_members tm WHERE tm.tenancy_id=t.id AND tm.user_id='.$uid.'))');
$ts=($finance&&!$staff)||$field?[]:rows('SELECT t.*,p.title property_title,p.owner_id,p.address_id,u.name tenant_name,u.public_id tenant_public_id,o.name owner_name,o.public_id owner_public_id FROM tenancies t JOIN properties p ON p.id=t.property_id JOIN users u ON u.id=t.head_tenant_id JOIN users o ON o.id=p.owner_id WHERE '.$scope.' ORDER BY t.id DESC LIMIT 1000');
$ids=array_column($ts,'id');$in=$ids?implode(',',array_map('intval',$ids)):'0';
$props=$field||($finance&&!$staff)?[]:rows('SELECT p.*, (SELECT path FROM property_photos WHERE property_id=p.id AND deleted_at IS NULL ORDER BY sort_order,id LIMIT 1) photo, (SELECT caption FROM property_photos WHERE property_id=p.id AND deleted_at IS NULL ORDER BY sort_order,id LIMIT 1) photo_caption FROM v_property_locations p WHERE '.($staff?'1=1':($agent?'EXISTS(SELECT 1 FROM appointments ax WHERE ax.property_id=p.id AND ax.assigned_to='.$uid.')':'p.owner_id='.$uid)).' ORDER BY p.id DESC LIMIT 1000');
$ascope=$staff?'1=1':"(a.requested_by=$uid OR a.assigned_to=$uid OR p.owner_id=$uid)";
$appointments=$field||($finance&&!$staff)?[]:rows("SELECT a.id,a.property_id,a.requested_by,a.assigned_to,a.kind,a.starts_at,a.status,a.notes,a.otp_verified_at,p.title property_title,requester.name requester_name,requester.phone requester_phone,owner.name property_owner_name,owner.phone property_owner_phone,ad.road_no,ad.house_no,ad.flat_no,ad.floor_no,u.name agent_name,u.phone agent_phone,u.public_id agent_public_id,u.verified_at agent_verified FROM appointments a JOIN properties p ON p.id=a.property_id JOIN users requester ON requester.id=a.requested_by JOIN users owner ON owner.id=p.owner_id JOIN addresses ad ON ad.id=p.address_id LEFT JOIN users u ON u.id=a.assigned_to WHERE $ascope ORDER BY a.starts_at LIMIT 1000");
$requests=$field||($finance&&!$staff)?[]:rows("SELECT m.id,m.tenancy_id,m.category_id,m.requested_by,m.provider_id,m.preferred_provider_id,m.title,m.description,m.urgency,m.appointment_at,m.owner_involved,m.owner_decision,m.pay_later,m.status,m.tenant_cost,m.owner_cost,m.provider_cost,m.cost_confirmed_at,m.otp_verified_at,m.created_at,c.name category,p.title property_title,p.owner_id,u.name provider_name,u.public_id provider_public_id,u.phone provider_phone,u.verified_at provider_verified,pp.business_name FROM maintenance_requests m JOIN service_categories c ON c.id=m.category_id JOIN tenancies t ON t.id=m.tenancy_id JOIN properties p ON p.id=t.property_id LEFT JOIN users u ON u.id=m.provider_id LEFT JOIN provider_profiles pp ON pp.user_id=m.provider_id WHERE m.tenancy_id IN($in)".($provider?' OR m.provider_id='.$uid:'').' ORDER BY m.id DESC LIMIT 1000');
attach_children($requests,'events','request_id','SELECT e.id,e.request_id,e.status,e.message,e.created_at,u.name actor FROM request_events e JOIN users u ON u.id=e.actor_id WHERE request_id IN(:ids) ORDER BY e.id');
attach_one($requests,'customer',"SELECT m.id parent_id,u.name,u.phone,a.house_no,a.house_name,a.road_no,a.floor_no,a.flat_no,l.name area FROM maintenance_requests m JOIN tenancies t ON t.id=m.tenancy_id JOIN users u ON u.id=m.requested_by JOIN properties p ON p.id=t.property_id JOIN addresses a ON a.id=p.address_id JOIN locations l ON l.id=a.location_id WHERE m.id IN(:ids)");
$financial=$staff||$finance||has($u,['tenant','owner']);$iscope=($staff||$finance)?'1=1':'(i.user_id='.$uid.' OR i.tenancy_id IN('.$in.'))';
$invoices=$financial?rows('SELECT i.*,u.name user_name FROM v_invoice_balances i JOIN users u ON u.id=i.user_id WHERE '.$iscope.' ORDER BY i.id DESC LIMIT 1000'):[];
attach_children($invoices,'items','invoice_id','SELECT * FROM invoice_items WHERE invoice_id IN(:ids) ORDER BY id');
$invIds=array_column($invoices,'id');$invIn=$invIds?implode(',',array_map('intval',$invIds)):'0';
$payments=$financial?rows('SELECT pay.*,u.name user_name,r.name reviewer_name,f.name confirmer_name FROM payments pay JOIN users u ON u.id=pay.user_id LEFT JOIN users r ON r.id=pay.reviewed_by LEFT JOIN users f ON f.id=pay.confirmed_by WHERE invoice_id IN('.$invIn.') ORDER BY pay.id DESC LIMIT 1000'):[];
$orders=$field||($finance&&!$staff)?[]:rows('SELECT o.*,p.title property_title,pp.business_name,provider.phone provider_phone FROM orders o JOIN tenancies t ON t.id=o.tenancy_id JOIN properties p ON p.id=t.property_id JOIN provider_profiles pp ON pp.user_id=o.provider_id JOIN users provider ON provider.id=o.provider_id WHERE '.($staff?'1=1':($agent?"o.tenancy_id IN($in)":"(o.user_id=$uid OR o.provider_id=$uid)")).' ORDER BY o.id DESC LIMIT 1000');
attach_children($orders,'items','order_id','SELECT oi.*,c.name product_name,c.unit FROM order_items oi JOIN catalog_products c ON c.id=oi.product_id WHERE oi.order_id IN(:ids) ORDER BY oi.id');
attach_one($orders,'delivery',"SELECT o.id parent_id,a.*,l.name location,u.name customer_name,u.phone customer_phone FROM orders o JOIN addresses a ON a.id=o.address_id JOIN locations l ON l.id=a.location_id JOIN users u ON u.id=o.user_id WHERE o.id IN(:ids)");
$contracts=$ids&&!$field&&!$finance?rows('SELECT c.* FROM contracts c WHERE c.tenancy_id IN('.$in.')'):[];
attach_children($contracts,'signatures','contract_id','SELECT cs.*,u.name FROM contract_signatures cs JOIN users u ON u.id=cs.user_id WHERE contract_id IN(:ids)');
$docs=$field?[]:rows("SELECT d.id,d.user_id,d.tenancy_id,d.property_id,d.kind,d.original_name,d.status,d.created_at,u.name account_name FROM documents d JOIN users u ON u.id=d.user_id WHERE ".($staff?'1=1':($finance?"d.kind='receipt' OR d.user_id=$uid":($provider?"d.user_id=$uid":"d.user_id=$uid OR d.tenancy_id IN($in)".($agent?" OR d.property_id IN(SELECT property_id FROM appointments WHERE assigned_to=$uid)":"")))).' ORDER BY d.id DESC LIMIT 1000');
$inspections=$field||($finance&&!$staff)?[]:rows('SELECT i.*,p.title property_title,u.name agent_name FROM inspections i JOIN properties p ON p.id=i.property_id JOIN users u ON u.id=i.agent_id WHERE '.($staff?'1=1':"(i.agent_id=$uid OR p.owner_id=$uid OR (i.status='approved' AND i.property_id IN(SELECT property_id FROM tenancies WHERE id IN($in))))").' ORDER BY i.id DESC LIMIT 1000');
attach_inspection_rooms($inspections);
$jobs=[];
if($provider&&$u['verified_at']){$pp=one('SELECT * FROM provider_profiles WHERE user_id=?',[$uid]);if($pp&&$pp['available']){$providerArea=(int)(one('SELECT parent_id FROM locations WHERE id=?',[$pp['location_id']])['parent_id']??0);$jobs=rows("SELECT m.id,m.title,m.description,m.urgency,m.pay_later,m.appointment_at,c.name category,l.name area,l.parent_id job_area_id,6371*ACOS(LEAST(1,GREATEST(-1,COS(RADIANS(?))*COS(RADIANS(a.latitude))*COS(RADIANS(a.longitude)-RADIANS(?))+SIN(RADIANS(?))*SIN(RADIANS(a.latitude))))) distance_km FROM maintenance_requests m JOIN service_categories c ON c.id=m.category_id JOIN tenancies t ON t.id=m.tenancy_id JOIN properties p ON p.id=t.property_id JOIN addresses a ON a.id=p.address_id JOIN locations l ON l.id=a.location_id WHERE m.status='approved' AND m.provider_id IS NULL AND ((m.urgency='instant' AND (m.preferred_provider_id IS NULL OR m.preferred_provider_id=$uid)) OR (m.urgency='scheduled' AND m.preferred_provider_id=$uid)) AND m.category_id IN(SELECT category_id FROM provider_categories WHERE provider_id=?) HAVING (urgency='instant' AND distance_km<=4) OR (urgency='scheduled' AND job_area_id=?) ORDER BY distance_km",[$pp['latitude'],$pp['longitude'],$pp['latitude'],$uid,$providerArea]);}}
$meals=$field||($finance&&!$staff)?[]:rows("SELECT s.*,m.name plan_name,m.meal,m.price_per_person,p.business_name,t.property_id,u.name customer_name,u.phone customer_phone, a.road_no,a.house_no,a.flat_no,a.floor_no,l.name area FROM meal_subscriptions s JOIN meal_plans m ON m.id=s.meal_plan_id JOIN provider_profiles p ON p.user_id=m.provider_id JOIN tenancies t ON t.id=s.tenancy_id JOIN properties pr ON pr.id=t.property_id JOIN addresses a ON a.id=pr.address_id JOIN locations l ON l.id=a.location_id JOIN users u ON u.id=s.user_id WHERE ".($staff?'1=1':"s.user_id=$uid OR m.provider_id=$uid".($agent?" OR s.tenancy_id IN($in)":"")."").' ORDER BY s.id DESC');
$roleSummary=[];
if($finance&&!$staff)$roleSummary=['ready_payments'=>(int)one("SELECT COUNT(*) n FROM payments WHERE status='reviewed'")['n'],'outstanding'=>one("SELECT COALESCE(SUM(balance),0) n FROM v_invoice_balances WHERE status='open'")['n'],'confirmed'=>one("SELECT COALESCE(SUM(amount),0) n FROM payments WHERE status='confirmed'")['n']];
if($super&&!$admin)$roleSummary=['requested_appointments'=>(int)one("SELECT COUNT(*) n FROM appointments WHERE status='requested'")['n'],'submitted_inspections'=>(int)one("SELECT COUNT(*) n FROM inspections WHERE status='submitted'")['n'],'pending_docs'=>(int)one("SELECT COUNT(*) n FROM documents WHERE status='pending'")['n'],'open_repairs'=>(int)one("SELECT COUNT(*) n FROM maintenance_requests WHERE status='open'")['n'],'submitted_payments'=>(int)one("SELECT COUNT(*) n FROM payments WHERE status='submitted'")['n'],'pending_tenancies'=>(int)one("SELECT COUNT(*) n FROM tenancies WHERE status='pending_verification'")['n'],'open_tickets'=>(int)one("SELECT COUNT(*) n FROM support_tickets WHERE status NOT IN('closed','resolved')")['n']];
if($agent&&!$staff)$roleSummary=['confirmed_visits'=>(int)one("SELECT COUNT(*) n FROM appointments WHERE assigned_to=? AND status='confirmed'",[$uid])['n'],'submitted_inspections'=>(int)one("SELECT COUNT(*) n FROM inspections WHERE agent_id=? AND status='submitted'",[$uid])['n'],'assigned_repairs'=>(int)one("SELECT COUNT(*) n FROM maintenance_requests m JOIN tenancies t ON t.id=m.tenancy_id WHERE m.status NOT IN('completed','cancelled') AND EXISTS(SELECT 1 FROM appointments a WHERE a.property_id=t.property_id AND a.assigned_to=?)",[$uid])['n']];
if(has($u,['owner'])&&!$staff)$roleSummary=['property_count'=>(int)one('SELECT COUNT(*) n FROM properties WHERE owner_id=?',[$uid])['n'],'occupied_homes'=>(int)one("SELECT COUNT(*) n FROM tenancies t JOIN properties p ON p.id=t.property_id WHERE p.owner_id=? AND t.status IN('active','notice')",[$uid])['n'],'expected_rent'=>one("SELECT COALESCE(SUM(t.rent),0) n FROM tenancies t JOIN properties p ON p.id=t.property_id WHERE p.owner_id=? AND t.status IN('active','notice')",[$uid])['n'],'repair_decisions'=>(int)one("SELECT COUNT(*) n FROM maintenance_requests m JOIN tenancies t ON t.id=m.tenancy_id JOIN properties p ON p.id=t.property_id WHERE p.owner_id=? AND m.owner_decision='pending'",[$uid])['n']];
respond(['role_summary'=>$roleSummary,'user'=>$u,'properties'=>$props,'tenancies'=>$ts,'members'=>$ids?rows('SELECT m.id,m.tenancy_id,m.user_id,CASE WHEN u.id IS NULL THEN m.name ELSE u.name END name,CASE WHEN m.user_id=t.head_tenant_id THEN "Head tenant" WHEN m.relationship="Head tenant" THEN "Household member" ELSE m.relationship END relationship,CASE WHEN u.id IS NULL THEN m.phone ELSE u.phone END phone,u.public_id FROM tenancy_members m JOIN tenancies t ON t.id=m.tenancy_id LEFT JOIN users u ON u.id=m.user_id WHERE m.tenancy_id IN('.$in.')'):[],'appointments'=>$appointments,'requests'=>$requests,'invoices'=>$invoices,'payments'=>$payments,'orders'=>$orders,'subscriptions'=>$meals,'contracts'=>$contracts,'documents'=>$docs,'inspections'=>$inspections,'saved'=>rows('SELECT property_id FROM saved_properties WHERE user_id=?',[$uid]),'visits'=>rows('SELECT v.*,p.title FROM property_visits v JOIN properties p ON p.id=v.property_id WHERE v.user_id=?',[$uid]),'notifications'=>rows('SELECT * FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT 100',[$uid]),'preferences'=>one('SELECT * FROM notification_preferences WHERE user_id=?',[$uid]),'rewards'=>one('SELECT COALESCE(SUM(points),0) points FROM reward_ledger WHERE user_id=?',[$uid]),'referrals'=>rows('SELECT * FROM referrals WHERE referrer_id=?',[$uid]),'tickets'=>rows('SELECT s.*,u.name account_name,u.phone account_phone,a.name assignee_name FROM support_tickets s JOIN users u ON u.id=s.user_id LEFT JOIN users a ON a.id=s.assigned_to WHERE '.($staff?'1=1':($agent?'s.user_id='.$uid.' OR s.assigned_to='.$uid:'s.user_id='.$uid)).' ORDER BY s.id DESC LIMIT 1000'),'complaints'=>$ids?rows('SELECT * FROM complaints WHERE tenancy_id IN('.$in.')'):[],'transfers'=>$ids?rows('SELECT * FROM tenancy_transfers WHERE tenancy_id IN('.$in.') OR to_user_id='.$uid):[],'bank_accounts'=>has($u,['owner','admin'])?rows('SELECT id,bank_name,account_name,RIGHT(account_number,4) account_last_four,routing_code FROM bank_accounts WHERE user_id=?',[$uid]):[],'agents'=>$staff?rows("SELECT u.id,u.name,u.public_id,u.phone FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE r.name='agent' AND u.status='active' AND u.verified_at IS NOT NULL"):[],'providers'=>$staff?rows('SELECT p.user_id,p.business_name,u.public_id,u.phone FROM provider_profiles p JOIN users u ON u.id=p.user_id WHERE u.verified_at IS NOT NULL AND u.status="active"'):[],'jobs'=>$jobs,'provider_profile'=>$provider?one('SELECT * FROM provider_profiles WHERE user_id=?',[$uid]):null,'provider_categories'=>$provider?array_column(rows('SELECT category_id FROM provider_categories WHERE provider_id=?',[$uid]),'category_id'):[],'campaigns'=>$field?rows('SELECT c.*,l.name area_name FROM campaigns c JOIN locations l ON l.id=c.location_id JOIN campaign_assignments ca ON ca.campaign_id=c.id WHERE ca.user_id=?',[$uid]):[],'server_date'=>date('Y-m-d'),'campaign_checklists'=>$field?rows('SELECT k.*,c.name campaign_name FROM campaign_checklists k JOIN campaigns c ON c.id=k.campaign_id WHERE k.user_id=? ORDER BY k.id DESC',[$uid]):[],'owners'=>$staff?rows("SELECT u.id,u.name,u.public_id FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE r.name='owner' AND u.status='active' AND u.deleted_at IS NULL ORDER BY u.name"):[],'support_staff'=>$staff?rows("SELECT u.id,u.name,r.name role FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE r.name IN('agent','supervisor') AND u.status='active' AND u.deleted_at IS NULL ORDER BY u.name"):[],'provider_products'=>$provider?rows('SELECT c.*,s.name category FROM catalog_products c JOIN service_categories s ON s.id=c.category_id WHERE c.provider_id=?',[$uid]):[],'provider_plans'=>$provider?rows('SELECT * FROM meal_plans WHERE provider_id=?',[$uid]):[],'provider_reviews'=>$provider?rows('SELECT r.id,r.rating,r.comment,r.created_at,u.name author FROM reviews r JOIN users u ON u.id=r.author_id WHERE r.subject_id=? ORDER BY r.id DESC',[$uid]):[],'training'=>$field||$agent?rows('SELECT * FROM training_materials WHERE audience=?',[$field?'field_agent':'agent']):[]]);
